26	export interface CertificateDetectionResult {
27	  hasCustomCertificates: boolean;
28	  certificateCount: number;
29	  scanDurationMs: number;
30	  errors: DetectionError[];
31	}
32	
33	export interface DetectionError {
34	  error: string;
35	  code?: string;
36	}
37	
38	export interface CertificateDetectionConfig {
39	  enableTelemetry: boolean;
40	  scanTimeoutMs: number;
41	  excludedExtensions: string[];
42	  validCertExtensions: string[];
43	  certDirectories: { system: string[]; user: string[] };
44	  followSymlinks: boolean;
45	}
